/**
 * Every API path the CLI calls whose 200 the document describes with a named schema, and that schema.
 *
 * A path is absent when the document does not describe it, or describes its 200 inline -- the client then
 * returns the body unvalidated rather than inventing a shape. test/unit/mcp-api-client.test.ts pins the
 * absent set so it can only ever shrink.
 */
export const CLI_RESPONSE_SCHEMAS = {
  "/v1/agent/explain-blockers": AgentRunBundleSchema,
  "/v1/agent/plan-next-work": AgentRunBundleSchema,
  "/v1/agent/prepare-pr-packet": AgentRunBundleSchema,
  "/v1/app/skipped-pr-audit": SkippedPrAuditExportSchema,
  "/v1/issue-rag/retrieve": IssueRagRetrieveResponseSchema,
  "/v1/lint/boundary-tests": SuggestBoundaryTestsResponseSchema,
  "/v1/lint/improvement-potential": CheckImprovementPotentialResponseSchema,
  "/v1/lint/issue-slop": CheckIssueSlopResponseSchema,
  "/v1/lint/open-pr-pressure": SimulateOpenPrPressureResponseSchema,
  "/v1/lint/pr-text": LintPrTextResponseSchema,
  "/v1/lint/slop-risk": CheckSlopRiskResponseSchema,
  "/v1/local/branch-analysis": LocalBranchAnalysisSchema,
  "/v1/opportunities/find": FindOpportunitiesResponseSchema,
  "/v1/preflight/local-diff": LocalDiffPreflightResultSchema,
  "/v1/preflight/pr": PreflightResultSchema,
  "/v1/preflight/review-risk": ReviewRiskExplanationSchema,
  "/v1/registry/changes": RegistryChangeReportSchema,
  "/v1/registry/snapshot": RegistrySnapshotSchema,
  "/v1/scoring/eligibility-plan": EligibilityPlanResponseSchema,
  "/v1/scoring/explain-breakdown": ScoreBreakdownResponseSchema,
  "/v1/scoring/preview": ScorePreviewSchema,
  "/v1/upstream/ruleset": UpstreamRulesetSnapshotSchema,
  "/v1/validate/focus-manifest": ValidateFocusManifestResponseSchema,
} as const;

/** A path the client validates. */
export type ValidatedApiPath = keyof typeof CLI_RESPONSE_SCHEMAS;

/** The parsed response type for a validated path -- what the CLI call sites get instead of `any`. */
export type ApiResponse<Path extends ValidatedApiPath> = z.infer<(typeof CLI_RESPONSE_SCHEMAS)[Path]>;
